              Dr ${totalDebits.toFixed(2)} / Cr ${totalCredits.toFixed(2)}
              {!isBalanced && ` (diff: $${Math.abs(diff).toFixed(2)})`}
            </span>
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => {
                localMappings.filter((mapping) => mapping.isDirty).forEach((mapping, index) => void saveMapping(mapping, index));
              }}
              disabled={!localMappings.some((mapping) => mapping.isDirty)}
              className="flex-1 text-xs bg-cyan-700 hover:bg-cyan-600 disabled:opacity-40 text-white py-2 rounded-lg transition-colors"
            >
              💾 Save All Changes
            </button>
            <button
              onClick={() => onTabChange('preview')}
              className="flex-1 text-xs bg-gray-700 hover:bg-gray-600 text-gray-300 py-2 rounded-lg transition-colors"
            >
              📋 Preview JE →
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { create, all } from 'mathjs';
import { RuleConfig } from '../types';

const safeMath = create(all);

export interface RuleDefinition {
  id: string;
  name: string;
  ruleType: 'COMBINE' | 'DEDUCT' | 'THRESHOLD' | 'FORMULA';
  config: RuleConfig;
  isActive: boolean;
}

/**
 * Apply a set of rules to raw Toast scan data fields.
 * Returns a transformed data object with computed fields added.
 */
export function applyRules(
  rawData: Record<string, number>,
  rules: RuleDefinition[]
): Record<string, number> {
  const result: Record<string, number> = { ...rawData };

  const activeRules = rules
    .filter((r) => r.isActive)
    .sort((a, b) => {
      // Apply DEDUCT rules last, COMBINE first
      const order = { COMBINE: 0, THRESHOLD: 1, FORMULA: 2, DEDUCT: 3 };
      return (order[a.ruleType] ?? 99) - (order[b.ruleType] ?? 99);
    });

  for (const rule of activeRules) {
    try {
      switch (rule.ruleType) {
        case 'COMBINE': {
          const { sourceFields, targetField } = rule.config;
          if (!sourceFields || !targetField) break;
          const combined = sourceFields.reduce((sum: number, field: string) => {
            return sum + (result[field] ?? 0);
          }, 0);
          result[targetField] = combined;
          console.log(`[RulesEngine] COMBINE "${rule.name}": ${sourceFields.join(' + ')} = ${combined} → ${targetField}`);
          break;
        }

        case 'DEDUCT': {
          const { sourceFields, targetField } = rule.config;
          if (!sourceFields || !targetField || sourceFields.length < 2) break;
          const base = result[sourceFields[0]] ?? 0;
          const deduction = sourceFields.slice(1).reduce((sum: number, field: string) => {
            return sum + (result[field] ?? 0);
          }, 0);
          result[targetField] = base - deduction;
          console.log(`[RulesEngine] DEDUCT "${rule.name}": ${base} - ${deduction} = ${result[targetField]} → ${targetField}`);
          break;
        }

        case 'THRESHOLD': {
          const { sourceFields, threshold, targetField } = rule.config;
          if (!sourceFields || threshold === undefined || !targetField) break;
          const value = result[sourceFields[0]] ?? 0;
          result[targetField] = value >= threshold ? value : 0;
          console.log(`[RulesEngine] THRESHOLD "${rule.name}": ${value} >= ${threshold}? → ${result[targetField]}`);
          break;
        }

        case 'FORMULA': {
          const { formula, targetField } = rule.config;
          if (!formula || !targetField) break;
          // Safe formula evaluation: replace field references with values
          const evaluatable = formula.replace(/\[([^\]]+)\]/g, (_: string, field: string) => {
            return String(result[field] ?? 0);
          });
          const compiled = safeMath.compile(evaluatable);
          const value = compiled.evaluate() as number;
          result[targetField] = value;
          console.log(`[RulesEngine] FORMULA "${rule.name}": ${evaluatable} = ${value} → ${targetField}`);
          break;
        }
      }
    } catch (err) {
      console.error(`[RulesEngine] Error applying rule "${rule.name}":`, err);
    }
  }

  return result;
}

export function applyRulesToLineItems(
  lineItems: Record<string, string>[],
  rules: RuleDefinition[]
): Record<string, string>[] {
  return lineItems.map((row) => {
    const numericRow: Record<string, number> = {};
    for (const [key, value] of Object.entries(row)) {
      const cleaned = String(value).replace(/[^0-9.\-]/g, '');
      const num = parseFloat(cleaned);
      if (!Number.isNaN(num)) {
        numericRow[key] = num;
      }
    }
    const transformed = applyRules(numericRow, rules);
    const resultRow: Record<string, string> = { ...row };
    for (const [key, value] of Object.entries(transformed)) {
      resultRow[key] = String(value);
    }
    return resultRow;
  });
}

import React from 'react';
import SearchableSelect from '../SearchableSelect';
import MappingEditModal from './MappingEditModal';
import type { LocalMapping } from './index';
import type { SelectOption } from '../SearchableSelect';
import type { QBAccount } from '../../types/qb';
import { validateMappingAccountType } from './index';

interface Props {
  localMappings: LocalMapping[];
  accountOptions: SelectOption[];
  accounts: QBAccount[];
  classOptions: SelectOption[];
  taxCodeOptions: SelectOption[];
  scanFieldOptions: SelectOption[];
  entityOptions: SelectOption[];
  saving: string | null;
  deleting: string | null;
  onUpdate: (localId: string, patch: Partial<LocalMapping>) => void;
  onSave: (mapping: LocalMapping, index: number) => void;
  onDelete: (mapping: LocalMapping) => void;
  onToggleExpand: (localId: string) => void;
  onAddMapping?: () => void;
  isBill?: boolean;
  isVendorCredit?: boolean;
}

export default function MappingTable({
  localMappings,
  accountOptions,
  classOptions,
  taxCodeOptions,
  scanFieldOptions,
  entityOptions,
  saving,
  deleting,
  onUpdate,
  onSave,
  onDelete,
  onToggleExpand,
  accounts,
  onAddMapping,
  isBill = false,
  isVendorCredit = false,
}: Props) {
  return (
    <div className="space-y-2">
      {localMappings.map((mapping, index) => (
        <MappingCard
          key={mapping.localId}
          mapping={mapping}
          index={index}
          accountOptions={accountOptions}
          accounts={accounts}
          classOptions={classOptions}
          taxCodeOptions={taxCodeOptions}
          scanFieldOptions={scanFieldOptions}
          entityOptions={entityOptions}
          isSaving={saving === mapping.localId}
          isDeleting={deleting === mapping.localId}
          onUpdate={(patch) => onUpdate(mapping.localId, patch)}
          onSave={() => onSave(mapping, index)}
          onDelete={() => onDelete(mapping)}
          onToggleExpand={() => onToggleExpand(mapping.localId)}
          isBill={isBill}
          isVendorCredit={isVendorCredit}
        />
      ))}
      {localMappings.length > 0 && onAddMapping && (
        <button
          type="button"
          onClick={onAddMapping}
          className="w-full py-2 text-sm text-teal-400 hover:text-teal-300 border border-dashed border-gray-600 rounded-md hover:border-teal-400 transition-colors"
        >
          + Add mapping
        </button>
      )}
    </div>
  );
}

interface MappingCardProps {
  mapping: LocalMapping;
  index: number;
  accountOptions: SelectOption[];
  accounts: QBAccount[];
  classOptions: SelectOption[];
  taxCodeOptions: SelectOption[];
  scanFieldOptions: SelectOption[];
  entityOptions: SelectOption[];
  isSaving: boolean;
  isDeleting: boolean;
  onUpdate: (patch: Partial<LocalMapping>) => void;
  onSave: () => void;
  onDelete: () => void;
  onToggleExpand: () => void;
  isBill: boolean;
  isVendorCredit: boolean;
}

function MappingCard({
  mapping,
  accountOptions,
  accounts,
  classOptions,
  taxCodeOptions,
  scanFieldOptions,
  entityOptions,
  isSaving,
  isDeleting,
  onUpdate,
  onSave,
  onDelete,
  onToggleExpand,
  isBill,
  isVendorCredit,
}: MappingCardProps) {
  const selectedAccount = accountOptions.find((option) => option.value === mapping.accountId);
  const selectedQBAccount = accounts.find((account) => account.Id === mapping.accountId);
  const warning = validateMappingAccountType(selectedQBAccount?.AccountType, mapping.postingType);

  const amountLabel = scanFieldOptions.find((option) => option.value === mapping.sourceField)?.subtitle ?? '$0.00';
  const hidePostingType = isBill || isVendorCredit;

  return (
    <div className={`bg-gray-800 border rounded-lg overflow-hidden transition-all ${
      mapping.isDirty ? 'border-cyan-700' : 'border-gray-700'
    }`}>
      <div className="flex items-center gap-2 px-3 py-2">
        <button
          type="button"
          onClick={onToggleExpand}
          className="text-gray-500 hover:text-gray-300 text-xs shrink-0"
        >
          {mapping.expanded ? '▼' : '▶'}
        </button>
        <div className="flex-1 min-w-0">
          {scanFieldOptions.length > 0 ? (
            <SearchableSelect
              options={scanFieldOptions}
              value={mapping.sourceField}
              onChange={(value) => onUpdate({ sourceField: value, description: value || mapping.description })}
              placeholder="Source field…"
            />
          ) : (
            <input
              className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1 focus:border-cyan-500 focus:outline-none"
              value={mapping.sourceField}
              onChange={(e) => onUpdate({ sourceField: e.target.value })}
              placeholder="Source field name…"
            />
          )}
        </div>
        {hidePostingType ? (
          <div className="flex flex-col items-end text-right text-xs text-gray-400 shrink-0">
            <span>Amount</span>
            <span className="text-white">{amountLabel}</span>
          </div>
        ) : (
          <div className="flex rounded overflow-hidden border border-gray-600 shrink-0">
            <button
              type="button"
              onClick={() => onUpdate({ postingType: 'Debit' })}
              className={`text-xs px-2 py-0.5 transition-colors ${
                mapping.postingType === 'Debit'
                  ? 'bg-blue-700 text-blue-100'
                  : 'bg-gray-900 text-gray-500 hover:text-gray-300'
              }`}
            >
              Dr
            </button>
            <button
              type="button"
              onClick={() => onUpdate({ postingType: 'Credit' })}
              className={`text-xs px-2 py-0.5 transition-colors ${
                mapping.postingType === 'Credit'
                  ? 'bg-emerald-700 text-emerald-100'
                  : 'bg-gray-900 text-gray-500 hover:text-gray-300'
              }`}
            >
              Cr
            </button>
          </div>
        )}
        <button
          type="button"
          onClick={onDelete}
          disabled={isDeleting}
          className="text-gray-600 hover:text-red-400 text-xs transition-colors shrink-0"
          title="Delete mapping"
        >
          🗑️
        </button>
      </div>

      <div className="px-3 pb-2">
        <SearchableSelect
          options={accountOptions}
          value={mapping.accountId}
          onChange={(value) => onUpdate({ accountId: value })}
          placeholder="QB Account…"
        />
        {selectedAccount && (
          <>
            <div className="text-xs text-gray-600 mt-0.5 truncate">{selectedAccount.subtitle}</div>
            {warning && (
              <div className="text-xs text-amber-400 mt-0.5 flex items-center gap-1 truncate" title={warning}>
                <span>⚠️</span>
                <span>{warning}</span>
              </div>
            )}
          </>
        )}
      </div>

      {mapping.expanded && (
        <MappingEditModal
          mapping={mapping}
          classOptions={classOptions}
          taxCodeOptions={taxCodeOptions}
          entityOptions={entityOptions}
          onUpdate={onUpdate}
          onSave={onSave}
          isSaving={isSaving}
        />
      )}
    </div>
  );
}

import { AppError, asyncHandler } from '../lib/errors';
import { Router, Response } from 'express';
import { authenticate, AuthRequest, locationFilter, requireFeaturePermission } from '../middleware/auth.middleware';
import { enforceEffectiveRole } from '../middleware/effective-role';
import { qbService } from '../services/qb.service';
import { suggestMappings } from '../lib/gemini';
import { prisma } from '../lib/prisma';

const router = Router();

router.use(authenticate, enforceEffectiveRole);

async function recordMappingPreference(locationId: string, sourceField: string, accountId: string, accountName: string) {
  if (!locationId || !sourceField || !accountId) return;
  await prisma.mappingPreference.upsert({
    where: {
      locationId_sourceField_accountId: {
        locationId,
        sourceField,
        accountId,
      },
    },
    update: {
      timesAccepted: { increment: 1 },
      lastUsedAt: new Date(),
    },
    create: {
      locationId,
      sourceField,
      accountId,
      accountName,
    },
  });
}

// ── PUT /api/mappings/:id ─────────────────────────────────────────────────────
router.put('/:id', requireFeaturePermission('map', 'write'), asyncHandler(async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const id = String(req.params['id']);
    const mapping = await prisma.mapping.findFirst({
      where: { id, location: locationFilter(req.user!) },
      include: { location: true },
    });

    if (!mapping) {
      throw new AppError('Mapping not found', 404);
    }

    const { sourceField, targetAccount, postingType, keepSeparate, targetClass, targetName, targetDescription, targetMemo, priority, templateId } =
      req.body as {
        sourceField?: string; targetAccount?: string; postingType?: string; keepSeparate?: boolean; targetClass?: string;
        targetName?: string; targetDescription?: string; targetMemo?: string; priority?: number; templateId?: string | null;
      };

    if (templateId !== undefined) {
      if (templateId !== null && templateId !== '') {
        const template = await prisma.template.findFirst({
          where: { id: templateId, locationId: mapping.locationId },
        });
        if (!template) {
          throw new AppError('Template not found', 404);
        }
      }
    }

    const updated = await prisma.mapping.update({
      where: { id },
      data: {
        ...(sourceField !== undefined && { sourceField }),
        ...(targetAccount !== undefined && { targetAccount }),
        ...(postingType !== undefined && { postingType }),
        ...(keepSeparate !== undefined && { keepSeparate }),
        ...(targetClass !== undefined && { targetClass }),
        ...(targetName !== undefined && { targetName }),
        ...(targetDescription !== undefined && { targetDescription }),
        ...(targetMemo !== undefined && { targetMemo }),
        ...(priority !== undefined && { priority }),
        ...(templateId !== undefined && { templateId: templateId || null }),
      },
    });

    await recordMappingPreference(
      mapping.locationId,
      sourceField ?? mapping.sourceField,
      targetAccount ?? mapping.targetAccount,
      targetAccount ?? mapping.targetAccount,
    );

    res.json(updated);
  } catch (err) {
    console.error('[Mappings] update error:', err);
    throw new AppError('Failed to update mapping', 500);
  }
}));

// ── DELETE /api/mappings/:id ──────────────────────────────────────────────────
router.delete('/:id', requireFeaturePermission('map', 'write'), asyncHandler(async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const id = String(req.params['id']);
    const mapping = await prisma.mapping.findFirst({
      where: { id, location: locationFilter(req.user!) },
      include: { location: true },
    });

    if (!mapping) {
      throw new AppError('Mapping not found', 404);
    }

    await prisma.mapping.delete({ where: { id } });
    res.json({ message: 'Mapping deleted' });
  } catch (err) {
    console.error('[Mappings] delete error:', err);
    throw new AppError('Failed to delete mapping', 500);
  }
}));

// ── POST /api/mappings/suggest ─────────────────────────────────────────────────
router.post('/suggest', requireFeaturePermission('map', 'read'), asyncHandler(async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const { locationId, scanFields, transactionType } = req.body as {
      locationId?: string;
      scanFields?: string[];
      transactionType?: string;
    };

    if (!locationId || !Array.isArray(scanFields) || scanFields.length === 0) {
      throw new AppError('locationId and scanFields are required', 400);
    }

    const location = await prisma.location.findFirst({
      where: { id: locationId, ...locationFilter(req.user!) },
    });

    if (!location) {
      throw new AppError('Location not found', 404);
    }

    const preferenceContext = await prisma.mappingPreference.findMany({
      where: {
        locationId,
        sourceField: { in: scanFields },
      },
      orderBy: [{ timesAccepted: 'desc' }, { lastUsedAt: 'desc' }],
      take: 20,
    });

    const preferenceText = preferenceContext.length > 0
      ? preferenceContext.map((preference) =>
          `- ${preference.sourceField} => ${preference.accountName} (${preference.timesAccepted} accepted)`,
        ).join('\n')
      : undefined;

    const suggestions = await qbService.callQB(req.user!.userId, async ({ accessToken, realmId }) => {
      const accounts = await qbService.getAccounts(realmId, accessToken);
      const accountNames = accounts.map((account) => account.FullyQualifiedName);
      const accountTypes = accounts.map((account) => ({
        name: account.FullyQualifiedName,
        type: account.AccountType,
        subType: account.AccountSubType || '',
      }));
      const aiSuggestions = await suggestMappings(scanFields, accountNames, transactionType, preferenceText, accountTypes);
      return aiSuggestions.map((suggestion) => {
        const matched = accounts.find((account) =>
          account.FullyQualifiedName.toLowerCase() === suggestion.accountName.toLowerCase() ||
          account.FullyQualifiedName.toLowerCase().includes(suggestion.accountName.toLowerCase()) ||
          account.FullyQualifiedName.toLowerCase().includes(suggestion.accountHint.toLowerCase()),
        );
        return {
          ...suggestion,
          accountId: matched?.Id,
        };
      });
    });

    res.json({ suggestions });
  } catch (err) {
    console.error('[Mappings] suggestion error:', err);
    throw new AppError('Failed to suggest mappings', 500);
  }
}));

