import type { ProductMapping, ExtractedLineItem } from '../../types';

export function extractLineItems(params: {
  lineItems: Record<string, string>[];
  columnMappings: Record<string, unknown>;
  productMappings: ProductMapping[];
  defaultPostingType: 'Credit' | 'Debit';
}): ExtractedLineItem[] {
  const {
    lineItems,
    columnMappings,
    productMappings,
    defaultPostingType,
  } = params;

  const productColumn = String(columnMappings.productColumn ?? '').trim();
  const amountColumn = String(columnMappings.amountColumn ?? '').trim();
  const descriptionColumn = String(columnMappings.descriptionColumn ?? '').trim();
  const classColumn = String(columnMappings.classColumn ?? '').trim();
  const taxCodeColumn = String(columnMappings.taxCodeColumn ?? '').trim();

  if (!productColumn || !amountColumn) {
    return [];
  }

  const normalizedMappings = productMappings.map((mapping) => ({
    key: mapping.productName?.trim().toLowerCase(),
    mapping,
  }));

  return lineItems.reduce<ExtractedLineItem[]>((acc, row) => {
    const productName = String(row[productColumn] ?? '').trim();
    const amountRaw = String(row[amountColumn] ?? '').trim();
    const amountValue = parseFloat(amountRaw.replace(/[^0-9.-]+/g, ''));

    if (!productName || Number.isNaN(amountValue) || amountValue === 0) {
      return acc;
    }

    const description = descriptionColumn
      ? String(row[descriptionColumn] ?? '').trim() || productName
      : productName;

    const classId = classColumn
      ? String(row[classColumn] ?? '').trim() || null
      : null;

    const taxCodeId = taxCodeColumn
      ? String(row[taxCodeColumn] ?? '').trim() || null
      : null;

    const normalizedProductName = productName.trim().toLowerCase();
    const matchedMapping = normalizedMappings.find((entry) => entry.key === normalizedProductName)?.mapping;

    const accountId = matchedMapping?.accountId ?? '';
    const accountName = '';
    const postingType = matchedMapping?.postingType ?? defaultPostingType;
    const matched = Boolean(matchedMapping);

    acc.push({
      productName,
      amount: amountValue,
      description,
      classId,
      taxCodeId,
      accountId,
      accountName,
      postingType,
      matched,
    });

    return acc;
  }, []);
}

export function getAutoFillSummary(items: ExtractedLineItem[]): {
  total: number;
  mapped: number;
  unmapped: number;
} {
  const total = items.length;
  const mapped = items.filter((item) => item.matched).length;
  const unmapped = total - mapped;
  return { total, mapped, unmapped };
}

import type { ReactNode } from 'react';

const MONTH_FORMATTER = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' });
const FULL_DATE_FORMATTER = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

export function relativeTime(dateString: string | null | undefined): string {
  if (dateString == null) {
    return 'Never';
  }

  const date = new Date(dateString);
  const timestamp = date.getTime();
  if (Number.isNaN(timestamp)) {
    return '-';
  }

  const now = Date.now();
  const diffMs = now - timestamp;
  const seconds = Math.floor(diffMs / 1000);

  if (seconds < 60) return 'just now';
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 30) return `${days}d ago`;
  if (days < 365) return MONTH_FORMATTER.format(date);

  return FULL_DATE_FORMATTER.format(date);
}

export function formatAction(action: string): string {
  const mapping: Record<string, string> = {
    ADMIN_APPROVED: 'Approved admin',
    ADMIN_REJECTED: 'Rejected admin',
    ADMIN_UPDATED: 'Updated admin',
    USER_INVITED: 'Invited user',
    ROLE_CHANGED: 'Changed role',
    PERMISSION_UPDATED: 'Updated permissions',
    TIMEBOMB_SET: 'Set trial expiration',
    USER_STATUS_CHANGED: 'Changed user status',
    USER_DISABLED: 'Disabled user',
    SCAN_SUBMITTED: 'Submitted scan',
    SCAN_SYNCED: 'Synced scan',
    SCAN_FAILED: 'Scan failed',
  };

  return mapping[action] ?? action
    .toLowerCase()
    .split('_')
    .map(part => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

export function trialCountdown(expiresAt: string | null | undefined): ReactNode {
  if (!expiresAt) {
    return <span className="text-xs text-gray-400 font-medium">No trial set</span>;
  }

  const expiry = new Date(expiresAt).getTime();
  if (Number.isNaN(expiry)) {
    return <span className="text-xs text-gray-400 font-medium">Invalid date</span>;
  }

  const now = Date.now();
  const diffMs = expiry - now;
  if (diffMs <= 0) {
    return <span className="text-xs text-red-400 font-medium">EXPIRED</span>;
  }

  const days = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
  const color = days <= 3 ? 'text-red-400' : days <= 7 ? 'text-orange-400' : 'text-emerald-400';
  return <span className={`text-xs font-medium ${color}`}>{days}d left</span>;
}

// Content script — runs on *://*.toasttab.com/* pages
// Real DOM scraper for Toast POS Sales Summary page
// Sections 1–17 extracted via data-testid selectors
export {};

// ---------------------------------------------------------------------------
// UTILITIES
